  Future<void> _initNewWallet() async {
    Exception? ex;
    final result = await showLoading(
      whileFuture: _initNewFuture(),
      context: context,
      message: l10n.addWalletGenerating,
      onException: (e) => ex = e,
    );

    // on failure show error message
    if (result == null) {
      if (mounted) {
        await showDialog<void>(
          context: context,
          builder: (_) => StackOkDialog(
            title: l10n.addWalletCreateError,
            message: ex?.toString() ?? l10n.commonUnknownError,
            maxWidth: 600,
          ),
        );
      }
      return;
    } else {
      if (mounted) {
        final nav = Navigator.of(context);
        unawaited(
          nav.pushNamed(
            NewWalletRecoveryPhraseView.routeName,
            arguments: Tuple2(result.$1, result.$2),
          ),
        );
      }
    }
  }

  Future<(Wallet, List<String>)> _initNewFuture() async {
    try {
      Map<String, dynamic>? otherDataJson;

      if (ref.read(pDuress)) {
        otherDataJson ??= {};
        otherDataJson[WalletInfoKeys.duressMarkedVisibleWalletKey] = true;
      }

      String? otherDataJsonString;
      if (otherDataJson != null && otherDataJson.isNotEmpty) {
        otherDataJsonString = jsonEncode(otherDataJson);
      }

      final info = WalletInfo.createNew(
        coin: widget.coin,
        name: widget.walletName,
        otherDataJsonString: otherDataJsonString,
      );

      var node = ref
          .read(nodeServiceChangeNotifierProvider)
          .getPrimaryNodeFor(currency: coin);

      if (node == null) {
        node = coin.defaultNode(isPrimary: true);
        await ref.read(nodeServiceChangeNotifierProvider).save(node, false);
      }

      String? mnemonicPassphrase;
      String? mnemonic;

      // set some sane default
      int wordCount = info.coin.defaultSeedPhraseLength;

      if (wordCount > 0) {
        if (ref.read(pNewWalletOptions) != null) {
          if (coin.hasMnemonicPassphraseSupport) {
            mnemonicPassphrase = ref
                .read(pNewWalletOptions)!
                .mnemonicPassphrase;
          }

          wordCount = ref.read(pNewWalletOptions)!.mnemonicWordsCount;
        } else {
          mnemonicPassphrase = "";
        }

        if (wordCount < 12 || 24 < wordCount || wordCount % 3 != 0) {
          throw Exception("Invalid word count");
        }

        final strength = (wordCount ~/ 3) * 32;

        mnemonic = bip39.generateMnemonic(strength: strength);
      }

      final wallet = await Wallet.create(
        walletInfo: info,
        mainDB: ref.read(mainDBProvider),
        secureStorageInterface: ref.read(secureStoreProvider),
        nodeService: ref.read(nodeServiceChangeNotifierProvider),
        prefs: ref.read(prefsChangeNotifierProvider),
        mnemonicPassphrase: mnemonicPassphrase,
        mnemonic: mnemonic,
      );

      await wallet.init();
      if (wallet is PivxWallet) await wallet.recordBirthday();

      // set checkbox back to unchecked to annoy users to agree again :P
      ref.read(checkBoxStateProvider.notifier).state = false;

      final fetchedMnemonic = await (wallet as MnemonicInterface)
          .getMnemonicAsWords();

      return (wallet, fetchedMnemonic);
    } catch (e, s) {
      Logging.instance.f("$e\n$s", error: e, stackTrace: s);
      rethrow;
    }
  }

